import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

const clampOpts = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

interface ValueSwapProps {
  values: string[];
  at: number | number[];
  duration?: number;
  distance?: number;
  direction?: "up" | "down";
  className?: string;
  style?: React.CSSProperties;
}

function ValueSwapBase({
  values,
  at,
  duration = 10,
  distance = 12,
  direction = "up",
  className,
  style,
}: ValueSwapProps) {
  const frame = useCurrentFrame();
  const ats = Array.isArray(at) ? at : [at];
  const d = direction === "down" ? -distance : distance;
  const count = Math.min(values.length, ats.length + 1);
  const rendered = values.slice(0, count);
  const sizer = rendered.reduce((a, b) => (b.length > a.length ? b : a), "");
  const swapP = (start: number) =>
    interpolate(frame, [start, start + duration], [0, 1], {
      ...clampOpts,
      easing: Easing.inOut(Easing.cubic),
    });
  return (
    <span
      className={className}
      style={{
        position: "relative",
        display: "inline-block",
        ...style,
      }}
    >
      <span style={{ visibility: "hidden" }}>{sizer}</span>
      {rendered.map((value, i) => {
        const pIn = i > 0 ? swapP(ats[i - 1]) : 1;
        const pOut = i < count - 1 ? swapP(ats[i]) : 0;
        const opacity = pIn * (1 - pOut);
        if (opacity <= 0.001) return null;
        const y = (1 - pIn) * d + pOut * -d;
        return (
          <span
            key={`${i}-${value}`}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              whiteSpace: "nowrap",
              opacity,
              translate: `0 ${y}px`,
            }}
          >
            {value}
          </span>
        );
      })}
    </span>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  duration: {
    type: "number",
    min: 4,
    max: 24,
    step: 1,
    default: 10,
    description: "Duration",
    hiddenFromList: false,
  },
  distance: {
    type: "number",
    min: 4,
    max: 32,
    step: 2,
    default: 12,
    description: "Distance",
    hiddenFromList: false,
  },
  direction: {
    type: "enum",
    default: "up",
    variants: {
      up: {},
      down: {},
    },
    description: "Direction",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 220,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 70,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["duration","distance","direction","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  duration: 10,
  distance: 12,
  direction: "up",
  speed: 1,
};

type ValueSwapElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof ValueSwapBase>;

const ValueSwapInner = forwardRef<
  HTMLDivElement,
  ValueSwapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 220, height = 70, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ValueSwap>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <ValueSwapBase
            {...(componentProps as unknown as ComponentProps<typeof ValueSwapBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const ValueSwap = Interactive.withSchema({
  Component: ValueSwapInner,
  componentName: "<ValueSwap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
